namn =   ["m_1", "m_2", "k_1", "k_2",  "c_1", "c_2", "v",    "H",  "L"];varden = {475,    53,    3021.6807,  158847.5098, 310,   1200,  65/3.6, 0.24, 1};d = dictionary(namn, varden);% Konstanta matrisernaM = [d{"m_1"}, 0; 0, d{"m_2"}]; K = [d{"k_1"}, (-1)*d{"k_1"}; (-1)*d{"k_1"}, d{"k_1"} + d{"k_2"}];C = [d{"c_1"}, (-1)*d{"c_1"}; (-1)*d{"c_1"}, d{"c_1"} + d{"c_2"}];% Konstanta matrismultiplikationernaM_K = (-1)*M\K;M_C = (-1)*M\C;%Sammansatt blockmatris AA = [0, 0, 1, 0;      0, 0, 0, 1;       M_K, M_C];d = insert(d, "M", {M});d = insert(d, "A", {A});save("var.mat", "d")